## Допущения

1. Модель `Quote` устроена так: `id: UUID`, `text: String`, `bookID: UUID`, `createdAt: Date`, и создаётся как `Quote(id:text:bookID:createdAt:)`. Если `bookID` или `id` — строки или порядок полей в создании другой, правка нужна только в `SwiftDataQuoteStore.swift` и в типах `BookQuote`.
2. `Quote` и хранилища лежат в одном модуле. Я назвал его `SlumpyCore`, это нужно только для строки импорта в тестах. Если `Quote` лежит в самом приложении, файлы 3 и 7 кладутся туда. Слова `public` нужны только для отдельного пакета, в приложении они ничему не мешают.
3. Хранилище само проставляет время создания. Пустой текст и пробелы не сохраняются, а лишние пробелы по краям обрезаются. Это решает экран, а не хранилище.
4. Удаление цитаты, которой уже нет, не считается ошибкой. Поэтому повторное нажатие «удалить» безопасно.
5. Список обновляется при открытии экрана и после каждого добавления или удаления на нём. Если в будущем цитаты будут меняться с другого экрана, пока этот открыт, понадобится подписка на изменения. Я её не делал, потому что сейчас она не нужна.
6. Если забыть подключить настоящее хранилище в `SlumpyApp`, приложение будет хранить цитаты только в памяти, и после перезапуска они пропадут. Подключение делается в одном месте, при запуске приложения, так что риск невелик.
7. Сообщения об ошибках сейчас на русском и не переведены.
8. При переходе на GRDB уже сохранённые цитаты нужно один раз скопировать из SwiftData в новую базу. Это отдельная задача на будущее, этот код её не решает.

Ниже весь код и объяснения. Файлов проекта у меня нет, поэтому код не компилировался и тесты не запускались. Первым делом прогоните его через Xcode или `scripts/check`.

## Как это устроено

Экраны знают только об «описании хранилища» (`QuoteStore`) и о простой структуре цитаты (`QuoteRecord`). SwiftData спрятана внутри одной реализации этого описания. Чтобы перейти на GRDB, нужно написать вторую реализацию и заменить одну строку в запуске приложения. Экраны при этом не меняются.

### 1. Описание хранилища. Логический пакет, без SwiftData и UI

```swift
// SlumpyCore/Sources/SlumpyCore/Quotes/QuoteStore.swift
import Foundation

/// A quote as screens see it: a plain value, independent of the storage engine.
public struct QuoteRecord: Identifiable, Hashable, Sendable {
    public let id: UUID
    public let bookID: UUID
    public let text: String
    public let createdAt: Date

    public init(id: UUID, bookID: UUID, text: String, createdAt: Date) {
        self.id = id
        self.bookID = bookID
        self.text = text
        self.createdAt = createdAt
    }

    /// Text as it is stored: trimmed at both ends; blank text is rejected.
    /// Every store implementation calls this, so they all behave the same.
    public static func validatedText(_ raw: String) throws -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { throw QuoteStoreError.emptyText }
        return trimmed
    }
}

public enum QuoteStoreError: Error, Equatable, Sendable {
    case emptyText
}

/// Storage for quotes. Screens depend on this protocol only.
public protocol QuoteStore: Sendable {
    /// Quotes of the book, newest first.
    func quotes(ofBook bookID: UUID) async throws -> [QuoteRecord]

    /// Saves a new quote and returns it as stored.
    /// Throws `QuoteStoreError.emptyText` for blank text; nothing is saved then.
    func addQuote(text: String, toBook bookID: UUID) async throws -> QuoteRecord

    /// Deletes the quote. Deleting a quote that no longer exists is not an error.
    func deleteQuote(id: UUID) async throws
}
```

```swift
// SlumpyCore/Sources/SlumpyCore/Quotes/InMemoryQuoteStore.swift
import Foundation

/// Keeps quotes in memory only. For previews and tests; data is lost on exit.
public actor InMemoryQuoteStore: QuoteStore {
    private var storage: [QuoteRecord]
    private let now: @Sendable () -> Date

    public init(quotes: [QuoteRecord] = [], now: @escaping @Sendable () -> Date = { .now }) {
        self.storage = quotes
        self.now = now
    }

    public func quotes(ofBook bookID: UUID) -> [QuoteRecord] {
        storage
            .filter { $0.bookID == bookID }
            .sorted { $0.createdAt > $1.createdAt }
    }

    public func addQuote(text: String, toBook bookID: UUID) throws -> QuoteRecord {
        let record = QuoteRecord(
            id: UUID(),
            bookID: bookID,
            text: try QuoteRecord.validatedText(text),
            createdAt: now()
        )
        storage.append(record)
        return record
    }

    public func deleteQuote(id: UUID) {
        storage.removeAll { $0.id == id }
    }
}
```

### 2. Реализация на SwiftData. Приложение, рядом с моделью `Quote`

Сама модель `Quote` остаётся как есть. Я исхожу из того, что она выглядит примерно так:

```swift
@Model
final class Quote {
    @Attribute(.unique) var id: UUID
    var text: String
    var bookID: UUID
    var createdAt: Date

    init(id: UUID, text: String, bookID: UUID, createdAt: Date) { … }
}
```

```swift
// Slumpy/Storage/SwiftDataQuoteStore.swift
import Foundation
import SwiftData
import SlumpyCore

/// QuoteStore backed by SwiftData. Runs on its own actor with its own ModelContext,
/// so the main thread is not blocked and SwiftData objects never leave this actor.
actor SwiftDataQuoteStore: QuoteStore, ModelActor {
    nonisolated let modelContainer: ModelContainer
    nonisolated let modelExecutor: any ModelExecutor
    private let now: @Sendable () -> Date

    init(modelContainer: ModelContainer, now: @escaping @Sendable () -> Date = { .now }) {
        self.modelContainer = modelContainer
        self.modelExecutor = DefaultSerialModelExecutor(modelContext: ModelContext(modelContainer))
        self.now = now
    }

    func quotes(ofBook bookID: UUID) throws -> [QuoteRecord] {
        let descriptor = FetchDescriptor<Quote>(
            predicate: #Predicate { $0.bookID == bookID },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        return try modelContext.fetch(descriptor).map { QuoteRecord($0) }
    }

    func addQuote(text: String, toBook bookID: UUID) throws -> QuoteRecord {
        let record = QuoteRecord(
            id: UUID(),
            bookID: bookID,
            text: try QuoteRecord.validatedText(text),
            createdAt: now()
        )
        modelContext.insert(
            Quote(id: record.id, text: record.text, bookID: record.bookID, createdAt: record.createdAt)
        )
        try saveOrRollBack()
        return record
    }

    func deleteQuote(id: UUID) throws {
        let quoteID = id
        let descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.id == quoteID })
        for quote in try modelContext.fetch(descriptor) {
            modelContext.delete(quote)
        }
        try saveOrRollBack()
    }

    /// A failed save must not leave the change pending, or a later save would apply it.
    private func saveOrRollBack() throws {
        do {
            try modelContext.save()
        } catch {
            modelContext.rollback()
            throw error
        }
    }
}

private extension QuoteRecord {
    init(_ quote: Quote) {
        self.init(id: quote.id, bookID: quote.bookID, text: quote.text, createdAt: quote.createdAt)
    }
}
```

