```swift
// Slumpy/Quotes/BookQuotesModel.swift
import Foundation
import Observation
import SlumpyCore

@MainActor
@Observable
final class BookQuotesModel {
    let bookID: UUID
    private(set) var quotes: [QuoteRecord] = []
    private(set) var errorMessage: String?
    private let store: any QuoteStore

    init(bookID: UUID, store: any QuoteStore) {
        self.bookID = bookID
        self.store = store
    }

    func load() async {
        do {
            quotes = try await store.quotes(ofBook: bookID)
            errorMessage = nil
        } catch {
            errorMessage = "Не удалось загрузить цитаты"
        }
    }

    func add(text: String) async {
        do {
            _ = try await store.addQuote(text: text, toBook: bookID)
            await load()
        } catch QuoteStoreError.emptyText {
            errorMessage = "Цитата пустая"
        } catch {
            errorMessage = "Не удалось сохранить цитату"
        }
    }

    func delete(id: UUID) async {
        do {
            try await store.deleteQuote(id: id)
            await load()
        } catch {
            errorMessage = "Не удалось удалить цитату"
        }
    }
}
```

```swift
// Slumpy/Quotes/BookQuotesView.swift (minimal example)
import SwiftUI
import SlumpyCore

struct BookQuotesView: View {
    @State private var model: BookQuotesModel

    init(bookID: UUID, store: any QuoteStore) {
        _model = State(initialValue: BookQuotesModel(bookID: bookID, store: store))
    }

    var body: some View {
        List {
            ForEach(model.quotes) { quote in
                Text(quote.text)
            }
            .onDelete { offsets in
                let ids = offsets.map { model.quotes[$0].id }
                Task { for id in ids { await model.delete(id: id) } }
            }
        }
        .task { await model.load() }
    }
}

