### 4. Тесты: одни и те же проверки для каждой реализации

```swift
// SlumpyTests/QuoteStoreTests.swift
import Foundation
import SwiftData
import Synchronization
import Testing
import SlumpyCore
@testable import Slumpy

/// Every QuoteStore implementation must pass the same tests.
/// When GRDB arrives, add a `.grdb` case here.
enum StoreKind: CaseIterable, Sendable, CustomTestStringConvertible {
    case swiftData
    case inMemory

    var testDescription: String {
        switch self {
        case .swiftData: "SwiftData"
        case .inMemory: "in memory"
        }
    }

    func make(now: @escaping @Sendable () -> Date = TickingClock().now) throws -> any QuoteStore {
        switch self {
        case .swiftData: SwiftDataQuoteStore(modelContainer: try makeInMemoryContainer(), now: now)
        case .inMemory: InMemoryQuoteStore(now: now)
        }
    }
}

func makeInMemoryContainer() throws -> ModelContainer {
    try ModelContainer(for: Quote.self, configurations: ModelConfiguration(isStoredInMemoryOnly: true))
}

/// Moves one second forward on every read, so creation order is unambiguous.
final class TickingClock: Sendable {
    private let seconds = Mutex(0)

    @Sendable func now() -> Date {
        seconds.withLock { value in
            value += 1
            return Date(timeIntervalSince1970: TimeInterval(value))
        }
    }
}

@Suite struct QuoteStoreContractTests {
    let book = UUID()

    @Test(arguments: StoreKind.allCases)
    func listsNewestFirst(kind: StoreKind) async throws {
        let store = try kind.make()
        _ = try await store.addQuote(text: "first", toBook: book)
        _ = try await store.addQuote(text: "second", toBook: book)

        let texts = try await store.quotes(ofBook: book).map(\.text)
        #expect(texts == ["second", "first"])
    }

    @Test(arguments: StoreKind.allCases)
    func listsOnlyQuotesOfThatBook(kind: StoreKind) async throws {
        let store = try kind.make()
        let otherBook = UUID()
        _ = try await store.addQuote(text: "mine", toBook: book)
        _ = try await store.addQuote(text: "other", toBook: otherBook)

        #expect(try await store.quotes(ofBook: book).map(\.text) == ["mine"])
    }

    @Test(arguments: StoreKind.allCases)
    func addReturnsWhatIsListed(kind: StoreKind) async throws {
        let store = try kind.make()
        let added = try await store.addQuote(text: "  to be  \n", toBook: book)

        #expect(added.text == "to be")
        #expect(added.bookID == book)
        #expect(try await store.quotes(ofBook: book) == [added])
    }

    @Test(arguments: StoreKind.allCases)
    func blankTextIsRejectedAndNotSaved(kind: StoreKind) async throws {
        let store = try kind.make()
        await #expect(throws: QuoteStoreError.emptyText) {
            _ = try await store.addQuote(text: "  \n ", toBook: book)
        }
        #expect(try await store.quotes(ofBook: book).isEmpty)
    }

    @Test(arguments: StoreKind.allCases)
    func deleteRemovesOnlyThatQuote(kind: StoreKind) async throws {
        let store = try kind.make()
        let keep = try await store.addQuote(text: "keep", toBook: book)
        let drop = try await store.addQuote(text: "drop", toBook: book)

        try await store.deleteQuote(id: drop.id)

        #expect(try await store.quotes(ofBook: book) == [keep])
    }

    @Test(arguments: StoreKind.allCases)
    func deletingMissingQuoteChangesNothing(kind: StoreKind) async throws {
        let store = try kind.make()
        let kept = try await store.addQuote(text: "kept", toBook: book)

        try await store.deleteQuote(id: UUID())

        #expect(try await store.quotes(ofBook: book) == [kept])
    }
}

@Suite struct SwiftDataQuoteStoreTests {
    /// A second store on the same database sees the changes: they were really saved.
    @Test func changesAreSavedToTheDatabase() async throws {
        let container = try makeInMemoryContainer()
        let book = UUID()
        let writer = SwiftDataQuoteStore(modelContainer: container)
        let kept = try await writer.addQuote(text: "kept", toBook: book)
        let dropped = try await writer.addQuote(text: "dropped", toBook: book)
        try await writer.deleteQuote(id: dropped.id)

        let reader = SwiftDataQuoteStore(modelContainer: container)
        #expect(try await reader.quotes(ofBook: book) == [kept])
    }
}
```

